@contextmanager
def using_language(language):
    token = _LANGUAGE.set(language if language in ('zh', 'en', 'es') else 'zh')
    try: yield
    finally: _LANGUAGE.reset(token)

def text(value, language=None):
    translations = _TRANSLATIONS.get(value)
    language = _LANGUAGE.get() if language is None else language
    return translations[0 if language == 'en' else 1] if translations and language != 'zh' else value

def localized(function):
    @wraps(function)
    def call(*args, **kwargs):
        language = kwargs.pop('language', None)
        if language is None: return function(*args, **kwargs)
        with using_language(language): return function(*args, **kwargs)
    return call

def localized_method(function):
    @wraps(function)
    def call(self, *args, **kwargs):
        with using_language(self.config.get('ui_language', 'zh')):
            return function(self, *args, **kwargs)
    return call

def language_for_root(root):
    for name in ('config.json', 'settings.json'):
        path = Path(root) / name
        if path.is_file():
            try: return json.loads(path.read_text(encoding='utf-8')).get('ui_language', 'zh')
            except (OSError, ValueError, AttributeError): return 'zh'
    return 'zh'

def localized_from_root(function):
    @wraps(function)
    def call(root, *args, **kwargs):
        with using_language(language_for_root(root)):
            return function(root, *args, **kwargs)
    return call
